arguments.command:
run_python < /dev/null 2>&1 << 'EOF'
import socket
# Try to resolve clickhouse
try:
    print("clickhouse:", socket.getaddrinfo('clickhouse', 8123))
except Exception as e:
    print("clickhouse failed:", e)

# Try localhost
try:
    print("localhost:", socket.getaddrinfo('localhost', 8123))
except Exception as e:
    print("localhost failed:", e)

# Try 127.0.0.1
try:
    print("127.0.0.1:", socket.getaddrinfo('127.0.0.1', 8123))
except Exception as e:
    print("127.0.0.1 failed:", e)

# Check /etc/hosts
import os
if os.path.exists('/etc/hosts'):
    with open('/etc/hosts') as f:
        print("hosts:", f.read())
EOF
